// Entry point: the module hooks.json names. Registers the command, draws the
// pane, and keeps the transcript index behind it fresh.
//
// Written against mods/types/claude-code.d.ts (Claude Code 2.1.277). The
// surface is early access and may change between releases; regenerate the
// declarations with /plugin-types rather than trusting this file's vintage.
import type { EngineInterface, On, PluginOptions } from "claude-code";
import { wholeLines, rangeArgv, sampleArgv, resumeCommand, sameDir, PROJECTS, SESSIONS, type FileInfo, type Host, type Store } from "./host.ts";
import { cachedSessions, sync, type Session } from "./scan.ts";
import { loadMeta, saveMeta, setMeta, mergeMeta, pruneMeta, metaFor, statusText, type Meta } from "./tags.ts";
import { loadConfig, registerFirst, DEFAULTS } from "./config.ts";
import { view, PAGE, type Model, type Actions } from "./view.ts";

const PANE_ID = "session-switcher";
const PANE_TITLE = "Sessions";
const DESCRIPTION = "Switch between recent sessions — filter, tag, and resume in the right directory";
// Drawn dim after the name as you type it, which is the only place the argument
// form is discoverable at the moment you'd want it.
const ARGUMENT_HINT = "[#tag | -#tag | new title | help]";

const HELP = [
  "/switcher                       open the switcher",
  "/switcher #wip #mods            tag this session (+#wip works too)",
  "/switcher -#mods                untag this session",
  "/switcher Token refresh bug     retitle this session",
  "/switcher #blocked on review    tag and retitle at once",
  "",
  "Arguments fold in: tags add, -#tag removes, and the title only changes when",
  "you type one. In the pane, t then a row's digit edits it there instead, and",
  "that form replaces what's on the row, because you can see it.",
  "",
  "This session's tags stay pinned under the prompt, with its switcher title",
  "when that differs from the session name.",
  "",
  "In the pane: type to filter · 1-9,0 resume · t tag · n/p page · Esc close",
].join("\n");

/**
 * The mod's whole state. It lives at module scope rather than inside
 * `register`'s closure because `claude plugin validate` only follows `$` into
 * functions declared at the top of this file — so `refresh` and `resume` have
 * to be top-level, and the state they work on has to reach them.
 */
const state = {
  host: null as Host | null,
  store: null as Store | null,
  commandName: null as string | null,
  isWindows: false,
  isOpen: false,
  syncing: false,
  sessions: [] as Session[],
  meta: {} as Record<string, Meta>,
  query: "",
  page: 0,
  mode: "resume" as "resume" | "tag",
  editing: null as { id: string; text: string } | null,
  refresh: 40,
  // The row an in-place resume switched to, standing in for this session
  // until its own transcript reaches the index.
  selfHint: null as Session | null,
};

const model = (): Model => ({
  sessions: state.sessions, meta: state.meta, query: state.query, page: state.page,
  mode: state.mode, editing: state.editing, syncing: state.syncing,
});

/** Folds in whatever changed since the last open, a row at a time. */
async function refresh($: EngineInterface): Promise<void> {
  const { host, store } = state;
  if (!host || !store || state.syncing) return;
  state.syncing = true;
  const byId = new Map(state.sessions.map((s) => [s.id, s]));
  try {
    await sync(store, host, (s) => {
      byId.set(s.id, s);
      state.sessions = [...byId.values()].sort((a, b) => b.lastActive - a.lastActive);
      $.ui.invalidate("ui.render");
    }, { refresh: state.refresh });
    pruneMeta(state.meta, state.sessions);
    await saveMeta(store, state.meta);
  } catch {
    /* a stale row beats a broken pane */
  } finally {
    state.syncing = false;
    $.ui.invalidate("ui.render");
  }
  // This session may only now have reached the index.
  await pinStatus($);
}

/**
 * Pins this session's tags under the prompt, so you can see what you're in
 * without opening the pane — plus its switcher title, when that isn't the name
 * the prompt border already draws. `$.ui.status` holds one line per plugin.
 *
 * An in-place resume doesn't fire `session.start` again, so `resume()` passes
 * the row it switched to as `hint`.
 */
async function pinStatus($: EngineInterface, hint?: Session): Promise<void> {
  const { host, store } = state;
  if (!host || !store) return;
  if (hint) state.selfHint = hint;
  try {
    const id = await $.session.id();
    const [sessions, names] = await Promise.all([cachedSessions(store, host), host.names().catch(() => ({}))]);
    const self = sessions.find((x) => x.id === id) ?? state.selfHint;
    const m = self ? metaFor(self, state.meta) : state.meta[id];
    $.ui.status(statusText(m, (names as Record<string, string>)[self?.id ?? id]));
  } catch { /* no line beats a broken session */ }
}

/**
 * Resuming works in place for a session from this project, and nowhere else.
 *
 * `$.process.run` captures a child's output and never hands it the terminal, so
 * shelling out to `claude --resume` does not switch you to anything — it starts
 * a headless second session and blocks until the timeout. `$.command.run` is the
 * right shape (it runs a slash command as if you typed it). A probe on 2.1.277
 * found no `/resume` among its commands; on 2.1.281 it is there and switches
 * immediately — but `/resume` only lists the current project's sessions.
 *
 * One from another project comes back "Session … was not found." as the
 * command's *output*, not a rejection, so a catch alone never saw it and the
 * click did nothing. Those get the command to paste instead — with the cwd,
 * because resuming one from the wrong directory drops you in the wrong repo.
 */
async function resume($: EngineInterface, s: Session): Promise<void> {
  await $.ui.close({ id: PANE_ID }).catch(() => undefined);
  state.isOpen = false;
  const here = await $.session.root().catch(() => "");
  if (sameDir(state.isWindows, here, s.projectPath)) {
    try {
      const out = (await $.command.run({ command: "resume", args: s.id })) as { text?: string } | undefined;
      if (!/not found/i.test(out?.text ?? "")) { await pinStatus($, s); return; }
    } catch { /* older builds: no /resume to run — fall through */ }
  }
  $.ui.log(resumeCommand(state.isWindows, s.projectPath, s.id));
}

export function register(on: On, options: PluginOptions) {
  // What the manifest's `userConfig` declares, as the person set it in
  // /config. The ordered fallback below still applies: a name they chose that
  // a built-in already owns costs them that candidate, not the mod.
  const chosen = typeof options.commandName === "string" ? options.commandName : null;
  const refreshCount = typeof options.refresh === "number" ? options.refresh : undefined;


  on("session.start", async ($, e, next) => {
    // The plugin doesn't know where home is; the engine does. Windows sets
    // USERPROFILE and often leaves HOME unset.
    const home = String((await $.env.get("HOME").catch(() => undefined))
      ?? (await $.env.get("USERPROFILE").catch(() => undefined)) ?? "");
    const isWindows = (await $.env.get("OS").catch(() => undefined)) === "Windows_NT";
    state.isWindows = isWindows;
    if (home) {
      // Built here, not imported: `$` is only ever followed into a function
      // declared in the same file, so the engine-side Host is spelled inline.
      const root = `${home}/${PROJECTS}`;
      const namesDir = `${home}/${SESSIONS}`;
      const run = async (argv: string[]): Promise<string> => {
        const { exitCode, stdout } = await $.process.run(argv, { timeoutMs: 30_000 });
        return exitCode === 0 ? stdout : "";
      };

      // One-entry memo: a scan calls linesFrom repeatedly on the same file, and
      // the $.fs.read path would otherwise re-read it whole each time.
      let memoPath = "";
      let memoLines: string[] | null = null;

      /** The whole file as lines, or null when it is too big for $.fs.read. */
      const wholeFile = async (path: string): Promise<string[] | null> => {
        if (memoPath === path) return memoLines;
        memoPath = path;
        memoLines = null;
        try {
          const text = await $.fs.read(path);
          memoLines = typeof text === "string" ? text.split("\n").filter(Boolean) : null;
        } catch {
          memoLines = null;   // over 4 MiB, or unreadable — the tools take it
        }
        return memoLines;
      };

      state.host = {
        async list(): Promise<FileInfo[]> {
          const out: FileInfo[] = [];
          for (const dir of await $.fs.list(root).catch(() => [])) {
            if (dir.kind !== "dir") continue;
            // One level deep only: sub-agent transcripts sit in <id>/subagents/
            // and are somebody else's session.
            for (const f of await $.fs.list(`${root}/${dir.name}`).catch(() => [])) {
              if (f.kind !== "file" || !f.name.endsWith(".jsonl")) continue;
              const path = `${root}/${dir.name}/${f.name}`;
              const st = await $.fs.stat(path).catch(() => null);
              if (st) out.push({ path, size: st.size, mtimeMs: st.mtimeMs });
            }
          }
          return out.sort((a, b) => b.mtimeMs - a.mtimeMs);
        },

        async names() {
          const out: Record<string, string> = {};
          const files = await $.fs.list(namesDir).catch(() => []);
          // Vendor-internal and undocumented: any failure here must degrade to
          // "no names found", never break the listing.
          for (const f of files) {
            if (f.kind !== "file" || !f.name.endsWith(".json")) continue;
            try {
              const raw = await $.fs.read(`${namesDir}/${f.name}`);
              const d = JSON.parse(typeof raw === "string" ? raw : "{}") as Record<string, unknown>;
              const id = d["sessionId"], name = d["name"];
              if (typeof id === "string" && typeof name === "string" && name
                  && d["nameSource"] !== "derived") out[id] = name;
            } catch { /* not ours to understand */ }
          }
          return out;
        },

        async linesFrom(path, from, max) {
          const all = await wholeFile(path);
          if (all) {
            // The common case: no subprocess, nothing platform-specific.
            return { lines: all.slice(from - 1, from - 1 + max), sawBytes: from - 1 < all.length };
          }
          const stdout = await run(rangeArgv(isWindows, path, from, max));
          // Measured: the engine cuts stdout at 4 MiB. wholeLines drops the
          // partial tail, and `sawBytes` lets the scanner recognise the one
          // case that cut hides — a single line bigger than the whole limit.
          return { lines: wholeLines(stdout + "\n"), sawBytes: stdout.length > 0 };
        },

        async sample(path, lines, end) {
          const all = await wholeFile(path);
          if (all) return end === "head" ? all.slice(0, lines) : all.slice(-lines);
          return wholeLines(await run(sampleArgv(isWindows, path, lines, end)) + "\n");
        },
      };

      state.store = {
        get: (key) => $.store.get(key),
        set: (key, value) => $.store.set(key, value),
      };
      const config = await loadConfig(state.store);
      state.refresh = refreshCount ?? config.refresh;
      state.commandName = await registerFirst(
        (spec) => $.command.register(spec),
        chosen ? [chosen, ...config.commands] : config.commands,
        // immediate: tagging is worth doing the moment you think of it, not
        // after the turn you're watching finishes.
        { description: DESCRIPTION, argumentHint: ARGUMENT_HINT, immediate: true },
      );
      // Every candidate taken is survivable: the pane's own hotkeys still work
      // once it is open, and a later release may free one up.
      if (!state.commandName) $.ui.log("session-switcher: no command name was free; open it from /help.");
      // The tag line is worth having, not worth delaying start for: not awaited.
      state.meta = await loadMeta(state.store);
      void pinStatus($);
    }
    return next(e);
  });

  on("command.run", { command: DEFAULTS.commands }, async ($, e, next) => {
    const { host, store } = state;
    if (!host || !store || e.command !== state.commandName) return next(e);

    // `/switcher #wip #mods` tags the session you're in and stays out of the
    // way — no pane, no picking your own row out of a list.
    const args = e.args.trim();
    if (args === "help" || args === "?" || args === "--help") return { text: HELP };
    if (args) {
      const id = await $.session.id();
      const [sessions, meta] = await Promise.all([cachedSessions(store, host), loadMeta(store)]);
      const self = sessions.find((x) => x.id === id) ?? null;
      const saved = mergeMeta(id, self, meta, args);
      await saveMeta(store, meta);
      state.meta = meta;
      await pinStatus($);
      const tags = saved.tags.length ? saved.tags.map((t) => "#" + t).join(" ") : "no tags";
      return { text: saved.title ? `${tags} · “${saved.title}”` : tags };
    }

    if (state.isOpen) {
      await $.ui.close({ id: PANE_ID }).catch(() => undefined);
      return { text: "Sessions closed." };
    }

    // Opens on the cached index — no transcript is read — then fills in.
    [state.sessions, state.meta] = await Promise.all([cachedSessions(store, host), loadMeta(store)]);
    state.query = "";
    state.page = 0;
    state.mode = "resume";
    state.editing = null;

    // Two lines a row, plus the header, the filter and the controls — asked
    // for explicitly so the list doesn't overflow and scroll its own chrome
    // out of view.
    await $.ui.open({ id: PANE_ID, title: PANE_TITLE, focus: true, closeOnEscape: true, rows: PAGE * 2 + 4 });
    state.isOpen = true;
    void refresh($);
    return {};
  });

  on("ui.render", { component: "Pane" }, async ($, e, next) => {
    if (e.requestId !== PANE_ID) return next(e);
    const table = await $.ui.resolve(e);
    // Element tables differ by surface — one without `Input` still gets rows.
    const { Box, Text, Button } = table;
    const Input = "Input" in table ? table.Input : undefined;

    const actions: Actions = {
      filter: (value) => { state.query = value; state.page = 0; $.ui.invalidate("ui.render"); },
      turnPage: (by) => { state.page = Math.max(0, state.page + by); $.ui.invalidate("ui.render"); },
      toggleMode: () => { state.mode = state.mode === "tag" ? "resume" : "tag"; $.ui.invalidate("ui.render"); },
      pick: (id) => {
        const s = state.sessions.find((x) => x.id === id);
        if (!s) return;
        if (state.mode === "tag") {
          const m = metaFor(s, state.meta);
          state.editing = { id, text: [m?.title, ...(m?.tags ?? []).map((t) => "#" + t)].filter(Boolean).join(" ") };
          return $.ui.invalidate("ui.render");
        }
        void resume($, s);
      },
      editTags: (value) => {
        const s = state.editing && state.sessions.find((x) => x.id === state.editing!.id);
        if (s && state.store) { setMeta(s, state.meta, value); void saveMeta(state.store, state.meta); }
        // Cheap when the edited row isn't this session: the same line re-pins.
        void pinStatus($);
        state.editing = null;
        state.mode = "resume";
        $.ui.invalidate("ui.render");
      },
    };

    return view({ Box, Text, Button, Input }, model(), actions);
  });

  on("ui.close", { id: PANE_ID }, async ($, e, next) => {
    state.isOpen = false;
    state.editing = null;
    return next(e);
  });

}

export { PAGE };

files.hooks/host.ts:
// The port between the scanner's logic and whatever can actually touch files.
//
// A hooks module runs in an environment of its own — no Node, no DOM — so the
// scanner cannot import `node:fs`. Worse, `$.fs.read` rejects any file over
// 4 MiB and offers no ranged read, and a 226 MB transcript is ordinary here.
//
// So a read tries `$.fs.read` first — no subprocess, every platform — and only
// a transcript too big for that falls back to `$.process.run`, which takes an
// argv (no shell) and hands back the child's stdout. That fallback is the one
// platform-specific corner in the mod: `sed`/`head`/`tail` on a POSIX host,
// `Get-Content` on Windows. Most sessions never reach it.
//
// This file holds only the port's shape and one pure helper. The engine-side
// implementation lives in register.ts, because `claude plugin validate`
// refuses a mod that passes `$` across an import: every `$.noun.verb(...)`
// must be spelled in the file that hooks. `test/node-host.ts` implements the
// same three calls on `node:fs`, which is what keeps the scanner testable.
export type FileInfo = { path: string; size: number; mtimeMs: number };

export type Host = {
  /** Session transcripts, newest first. Exactly one level deep. */
  list(): Promise<FileInfo[]>;
  /**
   * Lines `from` (1-based) onward, at most `max` of them. `sawBytes` says
   * whether the read returned anything at all, which is how the scanner tells
   * "end of file" from "one line too big to come back whole".
   */
  linesFrom(path: string, from: number, max: number): Promise<{ lines: string[]; sawBytes: boolean }>;
  /**
   * Session ids to the names you gave them, from Claude Code's own store.
   * `nameSource: "derived"` marks the CLI's auto-slug, not your choice, and is
   * left out — letting a weak slug outrank a real title inverts the order.
   */
  names(): Promise<Record<string, string>>;

  /** The first or last `lines` lines — a line budget, not a byte one, because
   *  that is the one shape both `head`/`tail` and PowerShell's `Get-Content`
   *  express directly. */
  sample(path: string, lines: number, end: "head" | "tail"): Promise<string[]>;
};

export type Store = {
  get(key: string): Promise<unknown>;
  set(key: string, value: unknown): Promise<void>;
};

export const PROJECTS = ".claude/projects";
export const SESSIONS = ".claude/sessions";

// The argv the fallback runs, built as pure functions so the Windows branch —
// the one corner of this mod that cannot be executed on a POSIX machine — is
// still reviewable and covered by tests.

/** PowerShell quoting: single quotes, with any inside doubled. */
export const psPath = (p: string) => `'${p.replace(/'/g, "''")}'`;

const ps = (script: string) => ["powershell", "-NoProfile", "-NonInteractive", "-Command", script];

/** Lines `from`..`from + max - 1`, printed without reading past them. */
export function rangeArgv(isWindows: boolean, path: string, from: number, max: number): string[] {
  const last = from + max - 1;
  return isWindows
    // -TotalCount stops the read at `last`; Skip drops the ones before `from`.
    ? ps(`Get-Content -LiteralPath ${psPath(path)} -Encoding UTF8 -TotalCount ${last} | Select-Object -Skip ${from - 1}`)
    // sed's trailing q is what stops it reading on to EOF after the range.
    : ["sed", "-n", `${from},${last}p;${last + 1}q`, path];
}

/** The first or last `lines` lines. */
export function sampleArgv(isWindows: boolean, path: string, lines: number, end: "head" | "tail"): string[] {
  return isWindows
    ? ps(`Get-Content -LiteralPath ${psPath(path)} -Encoding UTF8 ${end === "head" ? "-TotalCount" : "-Tail"} ${lines}`)
    : [end === "head" ? "head" : "tail", "-n", String(lines), path];
}

/**
 * POSIX shell quoting, only when the path needs it: a plain path stays readable,
 * one with a space or a quote in it is single-quoted, with any `'` closed,
 * escaped and reopened.
 */
export const shPath = (p: string) =>
  /^[\w@%+=:,./-]+$/.test(p) ? p : `'${p.replace(/'/g, `'\\''`)}'`;

/**
 * What to paste to resume a session in its own directory. Windows PowerShell
 * 5.1 has no `&&` — it is a parse error there — so the Windows form spells the
 * same "only if the cd worked" with `$?`.
 *
 * Both forms quote the directory. An unquoted POSIX path with a space in it
 * made `cd` fail, and the `&&` then quietly skipped the resume.
 */
export function resumeCommand(isWindows: boolean, dir: string, id: string): string {
  return isWindows
    ? `cd ${psPath(dir)}; if ($?) { claude --resume ${id} }`
    : `cd ${shPath(dir)} && claude --resume ${id}`;
}

/**
 * Whether two directories are the same project. Windows paths compare without
 * case and with either separator: `C:\Projects` and `c:/projects/` are one place.
 */
export function sameDir(isWindows: boolean, a: string, b: string): boolean {
  const norm = (p: string) => {
    const s = isWindows ? p.replace(/\//g, "\\").toLowerCase() : p;
    return s.replace(/[\\/]+$/, "");
  };
  return !!a && !!b && norm(a) === norm(b);
}

/** Splits a captured stdout chunk into whole lines, dropping a truncated tail. */
export function wholeLines(stdout: string, dropFirstPartial = false): string[] {
  const lines = stdout.split("\n");
  // `$.process.run` cuts stdout at the output limit, so the last line may be a
  // fragment; a tail read's *first* line is a fragment for the same reason.
  lines.pop();
  if (dropFirstPartial) lines.shift();
  return lines.filter(Boolean);
}

files.hooks/scan.ts:
// Turns ~/.claude/projects/<slug>/<session>.jsonl into one row per session,
// cheaply enough to run on a 400 MB transcript store.
//
// Three things keep it light:
//   1. stat-first. Files are ranked by mtime and only the newest are ever
//      opened; everything else is served from the cached index.
//   2. Append-only reads. Transcripts only grow, so a file that gained 40
//      lines is read from line `cached.lines + 1`, not line 1.
//   3. No JSON.parse in the hot loop. Every field the row needs is pulled
//      with a regex over the raw line; the only line ever parsed is the
//      single first user prompt. Attachment and tool-output lines — the
//      bulk of the bytes — are matched and discarded without being decoded.
//
// Nothing here touches the file system directly: see hooks/host.ts.
import type { Host, Store, FileInfo } from "./host.ts";

export const INDEX_VERSION = 3;
export const INDEX_KEY = "session-index";

const BIN_MS = 5 * 60_000;              // activity histogram resolution
const HEAD_LINES = 200;                 // enough for the opening prompt + cwd + branch
const TAIL_LINES = 400;                 // enough for the latest ai-title + last activity
const FULL_SCAN_MAX = 8 * 1024 * 1024;  // above this, sample head+tail instead
const LINES_PER_READ = 5_000;           // bounded: stdout is cut at 4 MiB (measured)
const READS_PER_FILE = 8;               // …so a huge delta catches up over a few opens
const FILES_CAP = 200;                  // stop collecting distinct edited paths here

export type Entry = {
  v: number;
  path: string;
  lines: number;       // complete lines already folded into this record
  size: number;
  mtimeMs: number;
  id: string;
  aiTitle?: string | undefined;   // newest wins — titles regenerate mid-session
  summary?: string | undefined;   // legacy fallback; real transcripts have none
  firstPrompt?: string | undefined;
  wrapperPrompt?: string | undefined;  // first user turn even when it was a wrapper
  cwd?: string | undefined;
  branch?: string | undefined;
  prompts: number;     // human turns, not every timestamped line
  files: string[];     // distinct file_path values seen in Edit/Write tool calls
  bins: Record<string, number>;   // wall-clock activity histogram, sparse
  firstTs?: number | undefined;
  lastTs?: number | undefined;
  partial: boolean;    // a huge file we sampled rather than read whole
};

export type Session = {
  id: string;
  title: string;
  firstPrompt: string;
  project: string;        // display name
  projectPath: string;    // full cwd — needed to resume in the right directory
  branch?: string | undefined;
  lastActive: number;
  prompts: number;
  filesTouched: number;
  activity: number[];     // 24 cells over the session's lifetime
  partial: boolean;
};

export async function loadIndex(store: Store): Promise<Record<string, Entry>> {
  const all = ((await store.get(INDEX_KEY).catch(() => null)) ?? {}) as Record<string, Entry>;
  // Drop anything written by an older extractor rather than trusting it.
  for (const [k, e] of Object.entries(all)) if (e?.v !== INDEX_VERSION) delete all[k];
  return all;
}

/** Instant: the cached index only, no transcript is opened. */
export async function cachedSessions(store: Store, host: Host, limit = 200): Promise<Session[]> {
  const [files, index, names] = await Promise.all([host.list(), loadIndex(store), host.names().catch(() => ({}))]);
  return files.slice(0, limit)
    .map((f) => toSession(index[f.path], f, names))
    .filter((s): s is Session => s !== null);
}

/**
 * Brings the index up to date, newest file first, invoking `onRow` as each one
 * lands so the open pane fills in progressively instead of blocking.
 */
export async function sync(
  store: Store,
  host: Host,
  onRow: (s: Session) => void,
  { refresh = 40 }: { refresh?: number } = {},
): Promise<void> {
  const [files, index, names] = await Promise.all([host.list(), loadIndex(store), host.names().catch(() => ({}))]);
  let touched = 0;
  let opened = 0;

  for (const f of files) {
    const cached = index[f.path];
    if (cached && cached.mtimeMs === f.mtimeMs && cached.size === f.size) continue;
    if (opened++ >= refresh) break;

    const entry = await scan(host, f, cached).catch(() => null);
    if (!entry) continue;
    index[f.path] = entry;
    touched++;
    const row = toSession(entry, f, names);
    if (row) onRow(row);
  }

  // Forget files that have been deleted, so the index can't grow forever.
  const live = new Set(files.map((f) => f.path));
  for (const k of Object.keys(index)) if (!live.has(k)) { delete index[k]; touched++; }

  if (touched) await store.set(INDEX_KEY, index).catch(() => undefined);
}

async function scan(host: Host, f: FileInfo, cached?: Entry): Promise<Entry> {
  // A file that shrank was rewritten, not appended to — start over.
  const resumable = cached && cached.v === INDEX_VERSION && cached.size <= f.size && !cached.partial;
  const e: Entry = resumable
    ? { ...cached, mtimeMs: f.mtimeMs, size: f.size, files: [...cached.files], bins: { ...cached.bins } }
    : { v: INDEX_VERSION, path: f.path, lines: 0, size: f.size, mtimeMs: f.mtimeMs,
        id: idOf(f.path), prompts: 0, files: [], bins: {}, partial: false };

  if (!resumable && f.size > FULL_SCAN_MAX) {
    // Too big to read whole on first sight: take the opening prompt from the
    // head and recent activity from the tail, and say so in the row.
    for (const line of await host.sample(f.path, HEAD_LINES, "head")) fold(line, e);
    for (const line of await host.sample(f.path, TAIL_LINES, "tail")) fold(line, e);
    e.partial = true;
    return e;
  }

  // Bounded per read, because the engine cuts stdout at 4 MiB; a file that
  // gained more than we take catches up over the next few opens.
  //
  // A read that returned bytes but no complete line means one line is larger
  // than the whole limit, so it can never come back whole. Stepping over it
  // costs that record; not stepping over it stalls the file for good.
  for (let i = 0; i < READS_PER_FILE; i++) {
    const { lines, sawBytes } = await host.linesFrom(f.path, e.lines + 1, LINES_PER_READ);
    if (!sawBytes) break;                       // end of file
    if (!lines.length) { e.lines += 1; continue; }  // see below
    for (const line of lines) fold(line, e);
    e.lines += lines.length;
    if (lines.length < LINES_PER_READ) break;
  }
  return e;
}

// Field extractors. Deliberately regex, not JSON.parse: the lines that hold
// most of the bytes (attachments, tool output) are ones we want to skip, and
// decoding them just to throw them away is where the naive version dies.
const RE_TS = /"timestamp":"([^"]+)"/;
const RE_CWD = /"cwd":"((?:[^"\\]|\\.)*)"/;
const RE_BRANCH = /"gitBranch":"((?:[^"\\]|\\.)*)"/;
const RE_AI_TITLE = /"aiTitle":"((?:[^"\\]|\\.)*)"/;
const RE_SUMMARY = /"summary":"((?:[^"\\]|\\.)*)"/;
const RE_EDIT = /"name":"(?:Edit|Write|MultiEdit|NotebookEdit)"[^}]*?"file_path":"((?:[^"\\]|\\.)*)"/g;

export function fold(line: string, e: Entry) {
  const ts = RE_TS.exec(line)?.[1];
  const t = ts ? Date.parse(ts) : NaN;

  if (e.cwd === undefined) { const m = RE_CWD.exec(line)?.[1]; if (m) e.cwd = unescape(m); }
  if (e.branch === undefined) {
    const m = RE_BRANCH.exec(line)?.[1];
    // "HEAD" is what a detached checkout — or a directory that is no repo at
    // all — reports. Drawing "on HEAD" tells you nothing.
    if (m && m !== "HEAD") e.branch = unescape(m);
  }

  if (line.includes('"type":"ai-title"')) {
    // Titles regenerate as a session goes on; the newest is the honest one.
    const m = RE_AI_TITLE.exec(line)?.[1];
    if (m) e.aiTitle = unescape(m);
    return;
  }
  if (line.includes('"type":"summary"')) {
    const m = RE_SUMMARY.exec(line)?.[1];
    if (m) e.summary = unescape(m);
    return;
  }

  const isUser = line.includes('"type":"user"');
  const isAssistant = !isUser && line.includes('"type":"assistant"');
  if (!isUser && !isAssistant) return;   // attachment, queue-operation, last-prompt, …

  // Only user/assistant turns count as activity, which is what the strip is
  // meant to show. Sub-agent chatter is somebody else's session.
  if (line.includes('"isSidechain":true')) return;

  if (!Number.isNaN(t)) {
    if (e.firstTs === undefined || t < e.firstTs) e.firstTs = t;
    if (e.lastTs === undefined || t > e.lastTs) e.lastTs = t;
    const bin = String(Math.floor(t / BIN_MS));
    e.bins[bin] = (e.bins[bin] ?? 0) + 1;
  }

  if (isUser) {
    if (line.includes('"tool_result"')) return;   // a tool's reply, not a human turn
    e.prompts++;
    if (e.firstPrompt === undefined) {
      const text = firstText(line);
      if (text && !isSystemWrapper(text)) e.firstPrompt = clean(text).slice(0, 300);
      // A session whose every turn is a wrapper still deserves better than
      // "Untitled": `clean` strips the tags, and what's inside one is usually
      // the command that ran.
      else if (text && e.wrapperPrompt === undefined) {
        const inner = clean(text).slice(0, 80);
        if (inner) e.wrapperPrompt = inner;
      }
    }
    return;
  }

  if (e.files.length < FILES_CAP && line.includes('"tool_use"')) {
    RE_EDIT.lastIndex = 0;
    for (let m: RegExpExecArray | null; (m = RE_EDIT.exec(line)); ) {
      const p = unescape(m[1] ?? "");
      if (p && !e.files.includes(p)) e.files.push(p);
      if (e.files.length >= FILES_CAP) break;
    }
  }
}

// The one place we decode a line — a single user turn, once per session.
function firstText(line: string): string | undefined {
  if (line.length > 1_000_000) return undefined;
  try {
    const c = (JSON.parse(line) as any)?.message?.content;
    if (typeof c === "string") return c;
    if (Array.isArray(c)) return c.map((b: any) => (typeof b?.text === "string" ? b.text : "")).join(" ");
  } catch { /* malformed line — no prompt from it */ }
  return undefined;
}

// Tags the CLI injects as a literal "user" turn: a slash command's banner, a
// hook's stdout, the IDE's selection, CLAUDE.md reminders. Taking the first
// user record at face value titles half your sessions "<system-reminder>".
// (List lifted from trailant, which learned it against real transcripts.)
const WRAPPERS = ["local-command-caveat", "local-command-stdout", "command-name", "command-message",
  "command-args", "system-reminder", "user-prompt-submit-hook", "ide_selection", "ide_diagnostics",
  "ide_opened_file", "recommended_plugins", "environment_context"];
function isSystemWrapper(text: string): boolean {
  const m = /^<([a-zA-Z][\w-]*)>/.exec(text.trim())?.[1];
  return !!m && WRAPPERS.includes(m);
}

// ---------------------------------------------------------------- rows

export function toSession(e: Entry | undefined, f: FileInfo, names: Record<string, string> = {}): Session | null {
  if (!e || (e.prompts === 0 && !e.aiTitle)) return null;
  // cwd from the transcript is authoritative; the directory name is a lossy
  // fallback (Claude Code maps "/", ".", ":" and "\" all onto "-").
  const projectPath = e.cwd || decodeProjectDir(dirName(f.path));
  return {
    id: e.id,
    // A name you gave the session outranks everything: it is the only one of
    // these that is a decision rather than a guess.
    title: clean(names[e.id] || e.aiTitle || e.summary || e.firstPrompt || e.wrapperPrompt || "Untitled session"),
    firstPrompt: e.firstPrompt ? clean(e.firstPrompt) : "",
    project: baseName(projectPath) || "?",
    projectPath,
    branch: e.branch,
    lastActive: e.lastTs ?? f.mtimeMs,
    prompts: e.prompts,
    filesTouched: e.files.length,
    activity: strip(e),
    partial: e.partial,
  };
}

/** Re-buckets the sparse wall-clock histogram into 24 cells at read time. */
function strip(e: Entry, n = 24): number[] {
  const out = new Array<number>(n).fill(0);
  const keys = Object.keys(e.bins);
  if (!keys.length) return out;
  const lo = e.firstTs ?? Number(keys[0]!) * BIN_MS;
  const span = Math.max(1, (e.lastTs ?? lo) - lo);
  for (const k of keys) {
    const i = Math.min(n - 1, Math.max(0, Math.floor(((Number(k) * BIN_MS - lo) / span) * n)));
    out[i]! += e.bins[k]!;
  }
  return out;
}

// No node:path here either — these are the only two pieces of it we need.
// Either separator: a Windows cwd is `C:\a\b` and has no "/" in it, so a
// "/"-only split handed back the whole path as the project's display name.
const baseName = (p: string) => p.slice(Math.max(p.lastIndexOf("/"), p.lastIndexOf("\\")) + 1);
const dirName = (p: string) => baseName(p.slice(0, p.lastIndexOf("/")));
const idOf = (p: string) => baseName(p).replace(/\.jsonl$/, "");
const decodeProjectDir = (name: string) =>
  name.startsWith("-") ? "/" + name.slice(1).replace(/-/g, "/") : name.replace(/-/g, "/");
const unescape = (s: string) => { try { return JSON.parse(`"${s}"`) as string; } catch { return s; } };
const clean = (s: string) => s.replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();

